############################################################################################################################

# [변경 이력 요약]
# - Ver7.21 (2026-07-25): 노트북 환경에서 간헐적으로 발생하던 이미지 삽입 실패 원인 수정
#     · 배경: 데스크탑은 정상이나 노트북마다 증상이 조금씩 다르게 발생
#            (썸네일이 실제로 존재함에도 "없다"/"경로가 틀렸다"로 처리되는 현상,
#             다양화 모드에서 소제목 이미지 누락과 함께 뒤이은 본문까지 유실되는 현상 -
#             특히 도입부 아래 첫 이미지 삽입 구간에서 두드러짐)
#     · 원인: _type_path_into_native_dialog()가 OS 네이티브 파일 열기 대화상자로
#            포커스 이동에 실패했을 때, 대화상자를 열어둔 채로 그냥 실패 처리만 하고
#            반환했음. 뒤이어 호출되는 _close_native_file_dialog()는 "현재 포커스를
#            가진 창"에 keybd_event(ESC)를 전역으로 흘려보내는 방식이었는데, 포커스가
#            애초에 대화상자로 이동하지 못한 상태이므로 이 ESC는 대화상자를 닫지 못하고
#            오히려 크롬(네이버 에디터) 쪽으로 새어 들어가 커서/서식 상태를 깨뜨림.
#            그 결과 대화상자는 화면에 남아 크롬 창을 모달로 막고, 뒤이은 클립보드
#            붙여넣기 폴백이나 다음 소제목 본문 타이핑이 엉뚱하게 처리됨. 노트북마다
#            렌더링/보안 소프트웨어 지연 정도가 달라 포커스 이동 성공률이 기기별로
#            편차가 컸던 것이 "노트북마다 증상이 다르다"는 관찰과 일치.
#     · 수정: _close_native_file_dialog()가 대상 창 핸들(hwnd)을 받아 포커스 상태와
#            무관하게 PostMessage(WM_CLOSE)로 해당 대화상자만 정확히 종료하도록 변경.
#            _type_path_into_native_dialog()의 모든 실패 분기(포커스 이동 실패, 타이핑
#            도중 포커스 이탈, Enter 이후 미종료)에서 자신이 직접 연 hwnd로 즉시 정리
#            하도록 수정하여, 실패한 대화상자가 화면에 방치되는 경우를 제거함.
#
# - Ver7.22 (2026-07-25): Ver7.21 실사용 테스트 중 발견된 후속 버그 수정
#     · 증상: 소제목 이미지 삽입 시 "파일 없음" 대화상자가 뜬 뒤(클립보드 폴백으로
#            결국 이미지는 삽입됨), ALT 태그가 방금 넣은 소제목 이미지가 아니라
#            엉뚱하게 상단 썸네일 이미지에 적용되는 현상 확인
#     · 원인: insert_image()가 ALT(캡션) 입력 시 "가장 마지막 div.se-caption"을 무조건
#            "방금 넣은 이미지의 캡션"이라고 가정했음. 클립보드 폴백 직후에는 SmartEditor가
#            새 이미지의 캡션 박스를 그려내기까지 시간차가 있는데, 이 시간차를 기다리지
#            않고 곧바로 조회하면 그 시점에 캡션 달린 이미지가 썸네일 하나뿐이라 그
#            썸네일의 캡션을 잘못 찾아가 덮어써버림.
#     · 수정: 이미지 삽입 "전" 캡션 개수를 미리 기록해두고, 삽입 "후" 실제로 캡션
#            개수가 늘어난 경우에만 그 캡션을 새 이미지의 것으로 신뢰. 몇 초를
#            기다려도 늘어나지 않으면 엉뚱한 이미지를 건드리지 않도록 ALT 입력을
#            안전하게 스킵(로그만 남김)하도록 변경.
#
# - Ver7.23 (2026-07-25): 사용자 요청에 따른 구조적 개선 3건
#     1) 클립보드 폴백 완전 제거
#        · 사유: 클립보드(Ctrl+V) 경유 삽입 시 네이버 에디터가 파일명을 "image.png"류
#          기본값으로 뭉개버려 SEO용 영문 파일명이 무의미해짐. 게다가 붙여넣기 후 실제
#          삽입 여부를 검증하지 않아 조용히 실패해도 "성공"으로 로그가 찍히는 문제도 있었음.
#        · 변경: insert_image() / _insert_two_images_native() 모두 네이티브(탐색기) 방식이
#          실패하면 폴백 없이 그 이미지만 건너뛰고 예외를 올려보냄. 상위 호출부(소제목
#          이미지 삽입 등)에 이미 있던 except 처리가 커서를 본문 끝으로 복귀시키고 본문
#          작성을 계속 이어가므로, "이미지 하나 실패 → 전체 포스팅 중단"은 발생하지 않음.
#     2) _type_path_into_native_dialog() 방식 전면 교체 (SendKeys → 메시지 기반)
#        · 기존 SendKeys 방식은 포커스 이동 성공 여부·타이핑 타이밍에 따라 노트북마다
#          성공률이 들쭉날쭉했음. 파일명 입력 컨트롤(고정 컨트롤ID 1148)에 WM_SETTEXT로
#          경로를 직접 주입하고, 열기 버튼(IDOK, 컨트롤ID 1)에 BM_CLICK을 직접 전달하는
#          방식으로 교체 - 포커스 상태·기기 성능과 무관하게 항상 동일하게 동작함.
#     3) 이미지 백업 폴더 신설 (Naver_temp_images_backup/날짜별)
#        · 삽입 시도 "전"에 생성된 이미지를 자동 정리 대상이 아닌 별도 폴더에 먼저
#          복사. 클립보드 폴백 제거로 실패 시 이미지를 그냥 건너뛰게 되므로, 나중에
#          수작업으로 찾아 넣을 수 있도록 원본을 항상 보존.
#     · 참고: Naver_temp_images 정리 타이밍(write_post 종료 시 1회, finally 블록)은
#       점검 결과 이상 없음을 확인 - 같은 포스팅 내에서 파일이 조기 삭제될 가능성 없음.
#
# - Ver7.24 (2026-07-25): 본문 줄바꿈이 원본 마크다운과 다르게 올라가던 문제 수정
#     · 증상: 마크다운에서 "변제금을\n다 냈습니다." 처럼 스타일상 한 문단을 두 줄로
#       나눠 쓴 경우에도, 에디터에는 각 줄 사이에 항상 빈 줄이 들어가 두 개의 별도
#       문단처럼 분리되어 올라감.
#     · 원인: 본문 처리 루프가 마크다운을 "줄 단위"로만 읽고, 그 줄의 마지막 문장에는
#       무조건 빈 줄(Enter 2회)을 고정해서 넣었음(_get_paragraph_breaks). 다음 줄이
#       실제 빈 줄인지, 아니면 내용이 계속 이어지는 줄인지 확인하는 로직이 없었음.
#     · 수정: _get_paragraph_breaks()가 0(이어쓰기)/1(줄바꿈만)/2(빈 줄) 3단계를
#       반환하도록 확장하고, 신설된 _is_markdown_paragraph_end()로 다음 줄을 미리
#       확인(lookahead)하여 실제 빈 줄/소제목/표/리스트/강조패턴일 때만 빈 줄(2),
#       내용이 계속 이어지면 줄바꿈만(1)을 넣도록 변경. 일반 문단·볼드 문단 두 분기에
#       동일하게 적용(리스트 항목 처리부에는 이미 같은 방식의 lookahead가 있었음 -
#       그 패턴과 일관되게 맞춤). 강조/주의 콜아웃 분기는 항상 빈 줄을 쓰는 의도된
#       설계라 그대로 유지.
#
# - Ver7.25 (2026-07-25): 썸네일 제목 30자 초과 시 절단 로직 개선
#     · 배경: GPT 제목 생성 API가 일시적으로 500/503 오류를 반복하면(OpenAI 서버측
#       이슈, SDK 기본 재시도 2회까지 소진 후 실패) 폴백으로 원본 제목을 그냥 앞에서
#       부터 30자까지 잘라 썼는데, "개인회생 변제금 완납, 면책신청은 왜 따로 해야
#       할까"가 "...면책신청은 왜"처럼 질문이 채 끝나기도 전에 잘려 썸네일에 박히는
#       문제가 있었음(실사용 로그로 확인).
#     · 수정: _smart_truncate_thumbnail_title() 신설. 원본에 쉼표가 있으면 절(clause)
#       단위로 다뤄 절 경계에서만 자르고, 한국어 제목 특성상 핵심 메시지가 보통 뒤
#       절에 오므로 뒤 절부터 채워나감(앞 절을 붙이면 30자를 넘는 경우 그 앞 절은
#       통째로 버려 절 중간에서 끊기지 않도록 함). 쉼표가 없거나 마지막 절 자체가
#       이미 30자를 넘으면 기존처럼 단어 단위로 자르되, 마지막 단어가 조사 하나로만
#       끝나 어색하게 마무리되면 그 단어까지 통째로 제거. GPT 성공 후 응답이 30자를
#       넘는 경우와 GPT 완전 실패 폴백 두 곳 모두 이 공용 로직으로 통일.
#     · 참고: 파일명 폴백(랜덤 8자 영문, _translate_keyword)은 기능·품질에 영향이
#       없어 별도 수정하지 않음.
#
# - Ver7.26 (2026-07-25): 썸네일 제목·파일명 생성 GPT 호출 재시도 횟수 축소
#     · 배경: generate_thumbnail_image_title(), _translate_keyword() 둘 다 OpenAI
#       클라이언트 SDK 기본 재시도(max_retries=2)를 그대로 쓰고 있었는데, 이 두 호출은
#       실패해도 이미 손실이 적은 폴백이 있음(제목: Ver7.25에서 절 경계를 지키는 폴백,
#       파일명: 랜덤 8자 영문 - 기능 영향 없음). OpenAI가 500/503을 반복하는 경우
#       (찰나의 오류가 아니라 몇 분짜리 장애) 재시도를 많이 해봐야 결과는 똑같이
#       실패하면서 시간만 날아가고, 파일명 변환은 한 포스팅에서 여러 번(썸네일/동영상/
#       소제목 이미지 등) 호출돼 누적 지연이 큼.
#     · 수정: 두 호출 모두 max_retries=1로 명시(2 → 1). 흔한 찰나의 실패는 1회
#       재시도로 여전히 커버하되, 장애성 실패일 때 폴백 전환 속도를 높임. 본문 내용을
#       생성하는 GPT/Gemini/Perplexity 호출(폴백이 마땅치 않음)은 대상에서 제외하고
#       그대로 유지.
#     · [즉시 정정] 실사용 로그에서 "Completions.create() got an unexpected keyword
#       argument 'max_retries'" 오류 확인 - 이 SDK 버전은 create() 호출에 max_retries를
#       직접 kwarg로 받지 않음(엉뚱하게 API 자체 파라미터로 전달되어 즉시 실패, 결과적
#       으로 매번 폴백행이 되어버림). client.with_options(max_retries=1).chat.completions
