#       typography in the image"(텍스트를 넣지 마라)가 같은 프롬프트 안에 서로 모순되게
#       공존하고 있었음 - 텍스트 포함이 의도된 설계이므로 모순되는 금지 문구를 제거하고,
#       대신 "지정된 한글 텍스트를 깨지거나 왜곡되지 않게 정확히 렌더링하라"는 지시로 교체.
#     · 원인 2: 프롬프트만으로는 저가 모델의 텍스트 렌더링 실패를 100% 막을 수 없음 -
#       생성 후 결과를 검증하는 단계가 전혀 없어 깨진 이미지가 그대로 사용됐음.
#     · 수정: _check_generated_image_text() 신설 - 생성된 이미지를 비전모델(gpt-4.1-mini)
#       에게 직접 보여주고, expected_text=None이면 "텍스트가 전혀 없어야 정상"(CTR 썸네일/
#       소제목, 인포그래픽GPT 소제목), expected_text=키워드면 "그 텍스트가 정확하고 읽을
#       수 있게 나와야 정상"(인포그래픽GPT 썸네일)으로 판정 기준을 다르게 검사.
#       generate_dalle_ctr_image()의 썸네일/소제목 두 분기, generate_infographic_gpt_
#       thumbnail(), generate_infographic_gpt_sub_image() 총 4곳의 AI 이미지 생성
#       루프에 삽입 - 문제 감지 시 기존 재시도 루프(최대 2회)에 편입되어 자동 재생성.
#       재시도를 다 소진해도 문제가 남으면 발행 자체는 막지 않고 로그만 남기고 진행
#       (다른 이미지 생성 실패 처리 패턴과 일관되게 유지). 검사 자체가 실패(네트워크
#       오류 등)하면 통과 처리하여 이 기능 때문에 포스팅이 막히는 일은 없도록 함.
#
# - Ver7.38 (2026-08-29): 본문 중 "2026. 08. 21"처럼 마침표 뒤 공백이 있는 날짜/
#   괄호 표기에서 문장 중간에 엉뚱하게 줄바꿈(엔터)이 들어가던 문제 수정
#     · 증상: "(2026. 08. 21)"처럼 마침표 뒤 공백이 있는 날짜가 본문 중간에 오면
#       "2026." / "08." / "21..." 세 조각으로 쪼개져 그 사이마다 엔터가 삽입됨.
#       괄호 안에 있어도 괄호 문자 자체는 분리를 막지 못해 동일하게 발생.
#     · 원인: 문장 분리 정규식 re.split(r'(?<![a-zA-Z][.!?])(?<=[.!?])\s+', ...)의
#       부정 룩비하인드가 "영문자 뒤 마침표"만 분리 대상에서 제외했음. 주석에는
#       "숫자 또는 한글 바로 뒤의 마침표는 분리 제외"라고 적혀 있었으나 실제 정규식
#       문자 클래스에는 숫자/한글이 빠져 있어 주석과 동작이 불일치했음. 줄 맨 앞이
#       "1. " 형태로 시작할 때만 예외 처리하는 별도 분기가 있었지만, 이는 줄 전체가
#       리스트 항목일 때만 적용되고 문장 중간의 날짜/항목 표기는 보호하지 못함.
#     · 수정: process_markdown_body() 내 문장 분리 정규식 3곳(일반 볼드 처리 분기,
#       특수 패턴 볼드 처리 분기, 일반 텍스트 분기)의 룩비하인드 문자 클래스를
#       [a-zA-Z] → [a-zA-Z0-9가-힣]로 확장. 부수적으로 "가.", "나." 같은 한글 순번
#       항목이 문장 중간에 올 때의 오분리도 함께 방지됨. 다양화 모드에서 이미지
#       삽입 위치를 계산하는 사전 줄 수 카운터(주석상 "포스팅과 동일한 기준")도
#       기존에는 이 예외 처리가 전혀 없어 실제 타이핑 로직과 기준이 어긋나 있었으므로
#       동일한 정규식으로 맞춤.
#
# - Ver7.39 (2026-08-29): 분할 이미지(1/2, 2/2) 삽입을 순차 2회 → 동시 1회로 변경
#     · 배경: _insert_two_images_native()가 이미지 버튼 클릭→네이티브 대화상자→
#       경로 주입→열기를 path1, path2에 대해 완전히 두 번 반복하는 구조였음. 대화상자를
#       두 번 여닫는 시차 사이에 순서/커서 상태가 어긋나는 경우가 있어 발행 후 수작업
#       수정이 필요했음.
#     · 수정: _type_path_into_native_dialog()가 abs_path에 리스트/튜플을 받으면
#       "경로1" "경로2" 형태로 묶어 WM_SETTEXT로 한 번에 주입하도록 확장(Windows 표준
#       공통 파일 대화상자의 다중 선택 표기 규칙 - 멀티셀렉트 허용 대화상자 기준).
#       기존 메시지 기반 주입/클릭 로직(컨트롤ID 1148 WM_SETTEXT, 컨트롤ID 1 BM_CLICK)
#       자체는 전혀 변경하지 않았고, 단일 경로(str) 호출부는 100% 기존과 동일하게 동작.
#       _insert_two_images_native()는 이미지 버튼 클릭 1회 + 대화상자 1회만 거치도록
#       재작성. 캡션(ALT) 처리는 스마트에디터가 두 장을 개별 이미지로 넣을지(캡션 2개)
#       하나의 포토팩으로 묶을지(캡션 1개) 확정할 수 없어, 삽입 후 새로 생긴 캡션 개수를
#       실측해 그 수만큼만 순서대로 채우도록 방어적으로 처리(1개면 순번 없이, 2개면
#       "라벨 1"/"라벨 2"로 순번 부여). 실패 시 처리(백업 후 예외를 상위로 올려 이 두
#       이미지만 건너뛰기)는 기존 단일 이미지 경로와 동일하게 유지.
#     · 참고: 스마트에디터가 다중 파일 선택을 실제로 어떻게 렌더링하는지는 Ver7.40에서
#       확인됨 - 파일 대화상자 닫힘 직후 "사진 첨부 방식"(개별사진/콜라주/슬라이드)을
#       고르는 브라우저 내 HTML 팝업이 별도로 뜸.
#
# - Ver7.40 (2026-08-29): 분할 이미지 동시 삽입 시 뜨는 "사진 첨부 방식" 팝업(개별사진/
#   콜라주/슬라이드) 자동 처리 - 콜라주 고정 선택
#     · 배경: Ver7.39에서 파일 대화상자에 두 경로를 동시 주입하는 데까지는 성공했지만,
#       실사용 확인 결과 대화상자가 닫힌 뒤 네이버 스마트에디터가 브라우저 내부에
#       "사진 첨부 방식" 팝업을 추가로 띄워 개별사진/콜라주/슬라이드 중 하나를 고르게
#       한다는 사실이 확인됨. 이 팝업은 OS 네이티브 대화상자가 아니라 순수 HTML 팝업
#       (div.se-popup-container.__se-pop-layer)이라 win32 메시지로는 처리 불가.
#     · 요구사항: 분할 이미지(가로로 이어붙여 하나처럼 보이게 하려는 의도)는 항상
#       "콜라주"(가로 우선 채움 배치) 고정 선택. 실제 팝업 HTML을 확인한 결과 라벨
#       (label[for="image-type-collage"]) 클릭 즉시 팝업이 닫히며 바로 삽입됨 - 별도
#       확인/적용 버튼 없음. 단일 이미지 삽입 시에는 이 팝업 자체가 뜨지 않음.
#     · 수정: _select_multi_image_layout() 신설 - div.se-popup-container.__se-pop-layer
#       등장을 대기하고, label.se-image-type-label[for='image-type-collage']를 클릭
#       (실패 시 input#image-type-collage를 JS로 직접 클릭하는 보조 경로 포함). 팝업이
#       애초에 뜨지 않으면(단일 이미지 등) 조용히 통과. _insert_two_images_native()가
#       네이티브 대화상자 성공 직후 이 함수를 호출하도록 연결. 팝업 등장 후 클릭까지
#       실패하면 기존 실패 처리 패턴과 동일하게 예외를 올려 해당 두 이미지만 건너뜀
#       (백업은 이미 삽입 시도 전에 저장돼 있으므로 수작업 복구 가능).
#
# - Ver7.41 (2026-08-29): insert_video()에도 이미지와 동일한 업로드 전 백업 적용
#     · 배경: _backup_generated_image()가 그동안 썸네일/소제목 이미지에만 적용돼 있었고
#       동영상은 백업 없이 바로 업로드를 시도했음. 동영상 업로드는 특정 기기(렌더링/
#       포커스 지연이 큰 노트북)에서 간헐적으로 실패하는 경우가 있는데(코드 로직 문제가
#       아니라 해당 기기의 타이밍 편차로 판단 - 다른 기기·재실행 시 정상 재현 안 됨),
#       실패해도 포스팅 자체는 계속 진행되도록 이미 상위(insert_kenburns_video)에서
#       예외를 흡수하고 있었지만, 실패한 동영상 원본은 그대로 유실되어 나중에 다시
#       만들어야 했음.
#     · 수정: insert_video() 맨 앞, 업로드 시도 전에 self._backup_generated_image(abs_path)
#       호출 추가 - 이미지와 동일한 백업 폴더(Naver_temp_images_backup/날짜별)에 저장되어
#       실패 시 수작업으로 찾아 업로드 가능. _backup_generated_image()는 파일 종류를
#       가리지 않는 단순 복사라 로직 변경 없이 그대로 재사용. 로그 문구만 "이미지 백업
#       실패" → "파일 백업 실패"로 일반화(이미지/동영상 공용이므로).
#
# - Ver7.42 (2026-08-30): 일부 기기에서 이미지/동영상 삽입이 전부 실패하던 문제 수정
#   (원인: 특정 기기의 Windows 누적 업데이트로 파일 열기 대화상자 내부 구조 변경)
#     · 증상: 특정 노트북 1대에서만 이미지(썸네일·소제목) 삽입이 100% 재현되는 실패
#       시작(오류: `(1421, 'GetDlgItem', '컨트롤 ID를 찾을 수 없습니다.')`). 실제 화면에서는
#       파일 탐색기 대화상자가 정상적으로 뜨지만 파일이름 입력란에 아무 것도 입력되지
#       않은 채 멈춰 있는 상태로 확인됨. 코드 구버전/신버전(Ver7.38~7.41) 모두 동일하게
#       재현되어 8/29 코드 수정과는 무관함이 확인됐고, 데스크탑·다른 노트북은 정상이었음.
#     · 원인: _type_path_into_native_dialog()가 파일이름 입력 컨트롤을 항상 고정
#       컨트롤ID(1148, 표준 공통대화상자 기준값)로만 찾고 있었음. 문제가 된 기기의
#       Windows 업데이트 기록을 확인한 결과, 하필 문제가 시작된 날짜에 Windows 10 22H2
#       누적 업데이트(KB5071959)와 보안 업데이트(KB5072653)가 설치된 것을 확인 - 이
#       업데이트(재부팅 후 적용) 이후로 그 기기의 파일 열기 대화상자 내부에서 더 이상
#       컨트롤ID 1148로 파일이름 입력란을 찾을 수 없게 된 것으로 판단됨(Windows 자체
#       구성요소 변경으로 추정되며, 프로그램 코드 문제가 아님). 이런 변경은 앞으로
#       다른 기기에도 순차적으로 배포될 수 있어 근본적인 보완이 필요하다고 판단.
#     · 수정: _find_filename_edit_control() 신설 - 기존처럼 고정 컨트롤ID(1148) 조회를
#       1차로 우선 시도(대부분 기기에서 여전히 정상 동작하므로 기존 동작 100% 유지,
#       속도도 그대로)하되, 이 조회가 실패하거나 예외를 던지면 대화상자 내부를
#       EnumChildWindows로 재귀 순회(자식의 자식까지 전부 순회되므로 컨트롤이 더 깊이
#       중첩되어도 대응 가능)하여 보이고(visible) 활성화된(enabled) "Edit" 클래스
#       컨트롤을 전부 수집한 뒤, 폭이 가장 넓고 가장 아래쪽에 위치한 것(검색창·주소창
#       보다 파일이름 입력란이 이 특징에 부합)을 골라 폴백으로 사용하도록 확장.
#       _type_path_into_native_dialog()는 이 함수를 통해서만 입력 컨트롤을 얻도록
#       변경했고, GetDlgItem 호출 자체에서 예외가 나는 경우까지 흡수하도록 함께 수정
#       (기존에는 반환값 None만 체크했고, 이번에 실제로 관측된 실패는 예외였음).
#
# - Ver7.43 (2026-08-30): Ver7.42 실사용 확인 결과, 문제의 그 기기는 Edit 클래스
#   컨트롤 자체가 대화상자 안에 전혀 존재하지 않는 것으로 확인됨 - UI Automation
#   폴백 3차 추가
#     · 배경: Ver7.42(동적 Edit 탐색)를 그 기기에 적용해 재실행한 결과, 로그에
#       "동적 탐색으로도 'Edit' 컨트롤을 찾지 못함"이 찍힘. 육안으로 그 대화상자가
#       실제 이미지가 보이는 정상적인 파일 선택 대화상자임을 사용자가 직접 확인 -
#       즉 "엉뚱한 창을 잘못 붙잡았다"는 가능성은 배제됨. 결론적으로 그 기기의 파일
#       열기 대화상자는 파일이름 입력란이 더 이상 표준 Win32 "Edit" 클래스 창(HWND)
#       으로 존재하지 않는(최신 렌더링 방식으로 바뀐 것으로 추정) 구조라, GetDlgItem/
#       EnumChildWindows 등 win32gui 기반 접근으로는 원천적으로 찾을 수 없음.
#     · 수정: _inject_path_via_uia() 신설 - win32gui 기반 탐색(1148 고정ID → Edit
#       재귀 탐색)이 모두 실패했을 때만 진입하는 3차 폴백으로, UI Automation(선택적
#       의존성 uiautomation 패키지)을 사용해 컨트롤 타입(Edit/ComboBox) 기준으로
#       의미 단위 탐색을 시도. 값 주입은 ValuePattern.SetValue()를 우선 시도하고,
#       지원하지 않으면 클릭 후 Ctrl+A로 기존 값을 지우고 직접 타이핑하는 방식으로
#       대체. "열기" 버튼도 이름 기준("열기"/"Open")으로 탐색해 클릭, 못 찾으면 Enter
#       키로 대체.
#     · 다른 기기 영향 없음 보장: (1) 이 폴백은 1148/Edit 탐색이 모두 실패했을 때만
#       도달하는 코드 경로라, 현재 정상 동작 중인 기기(1148 또는 Edit 탐색에서 이미
#       성공)에서는 물리적으로 실행되지 않음. (2) uiautomation 패키지는 다른 선택적
#       의존성(YOLO, Gemini)과 동일하게 try/except ImportError로 로드하므로, 미설치
#       기기에서는 이 블록 자체가 조용히 건너뛰어지고 기존 동작과 100% 동일하게 유지.
#     · 참고: 이 폴백은 실제 문제 기기에서의 검증 전 상태 - 로그로 성공 여부 확인 필요.
#
# - Ver7.44 (2026-08-30): Ver7.43 실사용 확인 결과, UI Automation으로도 파일이름
#   입력 컨트롤을 못 찾는 것으로 확인됨 - 추측 대신 대화상자 내부 구조를 그대로
#   로그로 남기는 진단 코드 추가
#     · 배경: Ver7.43(UIA 폴백)을 문제의 기기에 적용해 재실행한 결과, UIA 트리
#       탐색까지도 "UIA: 파일이름 입력 컨트롤(Edit)을 찾지 못함"으로 실패. win32
#       고정ID → win32 Edit 재귀 탐색 → UI Automation 타입 탐색까지 세 가지 서로
#       다른 방식이 모두 실패한 상황이라, 네 번째 방식을 또 추측으로 시도하기보다
#       그 대화상자 안에 실제로 어떤 구조가 있는지 직접 눈으로 확인하는 게 먼저라고
#       판단.
#     · 수정: _dump_dialog_diagnostic() 신설 - win32/UIA 방식이 전부 실패했을 때만
#       호출되어 (1) win32 자식 창 전체(EnumChildWindows, 클래스명·컨트롤ID·좌표·
#       보임/활성화 여부·텍스트) 목록과 (2) UI Automation 트리 전체(ControlType·
#       Name·ClassName·AutomationId, 깊이 6까지)를 그대로 로그에 남긴다. 삽입
#       성공/실패 판정이나 반환값에는 관여하지 않는 순수 로깅 전용 함수이며, 예외는
#       전부 흡수해 이 함수 때문에 포스팅 흐름이 끊기는 일이 없도록 함.
#     · 다른 기기 영향 없음: 위 3단계가 전부 실패했을 때만 도달하는 코드 경로라
#       정상 동작 중인 기기에는 전혀 영향 없음(로그 추가 외 동작 변경 없음).
#
# - Ver7.45 (2026-08-30): [원인 확정 및 근본 수정] 이미지 삽입 전 실패는 컨트롤을
#   못 찾은 게 아니라 애초에 엉뚱한(화면에 보이지도 않는) 창을 붙잡고 있던 것으로
#   확인됨
#     · 배경: Ver7.44 진단 로그로 실제 확인한 결과, 문제의 기기에서
#       `win32gui.FindWindow("#32770", None)`이 우리가 열려던 파일 대화상자가 아니라
#       완전히 무관한 다른 프로그램의 백그라운드 창("내 프로그램 설정", visible=0,
#       내부에 ListBox와 "추가..." 버튼만 존재 - 방화벽/보안 소프트웨어류의 허용
#       프로그램 목록 설정창으로 추정)을 매번 붙잡고 있었음. FindWindow는 "화면에
#       보이는지"를 전혀 따지지 않고 시스템 전체에서 클래스가 일치하는 첫 창을
#       그냥 반환하는데, 그 기기에 이 무관한 창이 상시 떠 있었던 것으로 보임.
#       Ver7.42(동적 Edit 탐색)/Ver7.43(UI Automation 폴백)이 전부 실패했던 건
#       이 잘못된 창 "안에서만" 계속 찾고 있었기 때문 - 애초에 그 창엔 파일이름
#       입력란이 없으니 어떤 방식으로도 찾을 수 없었음. Windows 누적 업데이트
#       (KB5071959 등)와의 타이밍 일치는 결과적으로 우연이었던 것으로 판단.
#     · 수정: 대화상자를 찾는 첫 단계를 `FindWindow(첫 매치 하나)`에서
#       `EnumWindows`로 그 순간 열려있는 모든 "#32770" 창을 수집한 뒤
#       `IsWindowVisible()`로 화면에 실제로 보이는 창만 후보로 남기는 방식으로
#       교체. 화면에 안 보이는 창(=우리와 무관한 백그라운드 창)은 애초에 후보에서
#       제외되므로, 이런 창 충돌이 다시 발생하지 않음. 후보가 2개 이상이면 경고
#       로그를 남기고 첫 번째를 사용(추후 실사용 중 이런 경우가 실제로 나오면
#       추가 보완).
#     · 다른 기기 영향: 정상 동작 중인 기기는 원래도 화면에 보이는 진짜 대화상자
#       하나만 열려 있었을 것이므로, 이 변경 후에도 동일한 창을 그대로 찾게 되어
#       동작 차이가 없음(오히려 앞으로 비슷한 창 충돌이 다른 기기에서 생기더라도
#       예방됨).
#     · 참고: Ver7.42~7.44에서 추가한 동적 Edit 탐색/UI Automation 폴백/진단 로그는
#       그대로 유지 - 이번 원인과 무관하게 향후 실제로 파일이름 컨트롤 구조가
#       다른 상황이 생기면 안전망으로 계속 유효함.
#
# - Ver7.46 (2026-09-03): 마크다운/키워드 원본 포스팅 전 백업 기능 신설
#     · 배경: 3번 모드("markdown")는 포스팅 성공 시 원본 md/txt 파일을 자동 삭제하고,
#       4번 모드("markdown_with_image")는 원본 md/txt(+케이스2일 때 썸네일·소제목
#       이미지까지)를 자동 삭제함. 템프이미지 백업(_backup_generated_image)과 달리
#       이 원본들은 삭제 전 별도 백업이 없어, 포스팅 후 내용을 다시 수정하고 싶거나
#       삽입 실패 여부가 애매했던 건을 원본과 대조해봐야 할 때 복구할 방법이 없었음.
#     · 수정: _backup_markdown_source() 신설(NaverBlogPoster) - 기존
#       _backup_generated_image()와 동일한 원리로, 실제 write_post() 호출(및 성공 시
#       원본 삭제) "전"에 Naver_blog_keyword_markdown_backup/날짜별/ 폴더로 미리 복사.
#       source_path가 파일이면 파일 하나만 복사하고, 폴더(4번 모드에서 키워드와 동일한
#       이름의 하위폴더를 쓰는 케이스)면 그 폴더 내부 모든 파일을 shutil.copytree로
#       폴더째 통째로 복사 - 개별 파일만 골라 복사하지 않음. 백업 실패는 항상 예외를
#       흡수해 포스팅 흐름에 영향을 주지 않음(기존 이미지 백업과 동일한 안전장치).
#       3번 모드는 파일 읽기 직후, 4번 모드는 소제목 목록 추출 직후(케이스1은 file_path,
#       케이스2는 _title_folder)에 각각 호출.
#     · [즉시 보완] 4번 모드 케이스1(공용풀, 하위폴더 없음)은 md/txt 파일만 백업되고
#       같은 키워드로 지정된 썸네일(png_thumbnail_path)은 별도 파일이라 백업 대상에서
#       빠져 있었음 - 케이스1에서도 png_thumbnail_path가 존재하면 _backup_markdown_source()
#       를 한 번 더 호출해 썸네일도 함께 복사하도록 보완(케이스2는 폴더째 복사라 이미 포함됨).

# - Ver7.47 (2026-09-05): 복지로/정책뉴스 통합 키워드·포스팅 파일 관리 기능 신설
#     · 배경: 하나의 블로그 안에서 복지로/정책뉴스 두 게시판(카테고리)을 운영 중인데,
#       두 게시판은 각자 별도의 서브프로그램·키워드 파일·포스팅 이력 파일로 완전히
#       분리 관리되고, 기본설정 탭에서는 키워드/포스팅 파일을 1개만 지정할 수 있어
#       두 게시판을 오가며 작업하려면 그때그때 파일 경로를 다시 지정해야 했음.
#     · 수정: 신설한 Naver_blog_unified_management_module.py(선택적 import, 없어도
#       기존 동작에 영향 없음)를 통해 두 게시판의 키워드/포스팅을 카테고리로 구분해
#       담는 "통합 키워드/포스팅 파일" 체계를 추가함. 기본설정 탭(auto_frame)에
#       "복지로/정책뉴스 통합 파일 사용" 체크박스와 "통합 파일 관리" 버튼을 새 컬럼에
#       추가(기존 row 배치는 전혀 건드리지 않음). 체크박스를 켜면 통합관리 모듈의
#       설정값으로 keyword_file_path/posting_result_path를 자동으로 맞춰서, 기존
#       get_next_keyword 등 키워드 처리 로직은 코드 변경 없이 그대로 재사용됨(파일
#       경로만 통합 파일로 바뀔 뿐). [즉시 보완 x2] 처음엔 auto_frame의 포스팅
#       결과 파일 행 오른쪽 → 계정 정보 프레임의 휴먼 활동 체크박스 옆으로 옮겼으나
#       두 자리 모두 이미 폭 넓은 입력창들로 채워져 있어 창 가로폭이 화면을 넘어가는
#       문제가 반복됨. 최종적으로 "포스팅 가능 시간대" 행(라벨+폭3 콤보박스뿐이라
#       다른 행보다 짧음) 끝에 이어붙이는 것으로 확정 - 새 grid 열을 만들지 않고
#       기존 pack 행에 이어붙이므로 창 폭에 영향이 없음.
#       포스팅 한 건이 끝나 update_excel_after_posting()을
#       호출한 직후, 통합 파일 사용 모드일 때만 sync_completion_to_origin(keyword)을
#       한 번 더 호출해 방금 완료된 키워드를 원본(복지로 또는 정책뉴스) 키워드/포스팅
#       파일에도 자동으로 반영함(등록 순서 = 처리 순서라는 전제 하에, 원본 키워드
#       파일의 "상태 비어있는 첫 행"에 매칭 - 텍스트 매칭이나 행 번호 추적 불필요).
#       use_unified_files 설정값은 기존 config 저장/로드 루틴에 함께 저장/복원되도록
#       추가함. 복지로/정책뉴스 두 서브프로그램(각자 파일)에도 통합 키워드 파일 경로
#       설정 필드와 dual-write 호출을 최소 추가함(자세한 내용은 각 서브프로그램 파일의
#       변경 이력 참고). 원본 키워드/포스팅 파일의 기존 컬럼 구조는 전혀 변경하지
#       않음 - 다른 서브프로그램이 그대로 참조하기 때문.
#     · [사용자 지적사항 반영] "실수로 체크박스를 눌렀다 뺐다 하며 작업하면 데이터가
#       꼬일 것"이라는 지적에 따라, 체크박스가 바뀔 때마다(켜기/끄기 모두) 확인 팝업을
#       추가함. 켤 때는 "켜면 계속 켠 채로 써야 한다"는 경고와 함께 전환될 파일 경로를
#       보여주고 동의해야 실제로 전환됨(거부하면 체크 원복). 이때 전환 직전의 개별
#       파일 경로를 self._pre_unified_keyword_path/_posting_path에 기억해둠. 끌 때는
#       [예: 개별 파일로 복원 / 아니오: 지금 경로 유지 / 취소: 끄기 자체를 취소]
#       3지선다 팝업을 띄워, 체크만 꺼지고 파일 경로는 여전히 통합 파일을 가리키는
#       채로 남는(사용자가 우려한 상황 그 자체) 문제를 없앰. _on_use_unified_files_
#       toggled()는 이제 얇은 분기(_handle_unified_files_checked/_unchecked 호출)만
#       한다.
#     · [즉시 보완 x3, 세로 공간 확보] "복지로/정책뉴스 통합 파일 사용" 체크박스와
#       "통합 파일 관리" 버튼은 서로 짝이므로 세트로 함께 posting_time_frame에서
#       계정 정보 프레임(account_frame)의 휴먼 활동 체크박스 옆으로 이동함. 이
#       셋(휴먼 활동 체크박스/구분선/통합 파일 체크박스/버튼)을 담을
#       human_activity_frame sub-frame을 새로 만들어 pack으로 나란히 배치함.
#       그리고 "포스팅 주기(분)" 라벨+입력창과 "다음 포스팅: -" 표시를 원래
#       같은 줄(auto_frame row=4)에 있던 것을 통째로 "포스팅 가능 시간대" 행
#       (posting_time_frame) 끝으로 이동시켜, auto_frame row=4를 더 이상 쓰지
#       않게 되어 세로줄 하나를 온전히 절약함. 마지막으로 계정 정보 프레임에
#       체크박스+버튼이 추가로 들어오며 그 행(row=5)이 넓어진 것을 상쇄하기
#       위해 naver_id_entry/blog_name_entry의 입력창 폭을 width=30 → 20으로
#       축소함(가로창이 화면 밖으로 넘어가는 것 방지).

# - Ver9.16 (2026-10-08): 코드 점검에서 찾은 버그 4건 수정 (정책뉴스·복지로·지식인 공통)
#     1) ffmpeg.exe가 없는 PC에서 프로그램이 아예 시작되지 않던 문제 - FFMPEG_EXE 확인
#        경고가 logger 생성(setup_logging)보다 앞에 있어 NameError가 났음. 확인을
#        logger 생성 뒤로 옮김(동작은 같음: 경고만 남기고 동영상 재인코딩은 건너뜀).
#     2) "지정 시간 시작" 모드 - 랜덤조정(±15분)한 시작 시각이 이미 지났는데 조정값이
#        0 이상이면 wait_seconds가 정해지지 않아 오류로 자동 포스팅이 멈췄음(오류는
#        콘솔에만 찍힘). 이미 지났으면 조정값 부호와 무관하게 즉시 시작하도록 수정.
#        대기 후 다시 들어올 때 조정값을 새로 뽑아 시작이 또 밀리던 것도, 시작 버튼을
#        누를 때 한 번만 정하도록(self._start_time_target) 함께 수정.
#     3) 해시태그가 1~2개뿐이면 random.randint(3, 2) 오류로 태그가 하나도 안 들어가던
#        문제 - 3개 미만이면 있는 만큼 모두 넣음(3개 이상은 기존처럼 3~5개 랜덤).
#     4) "## "가 아닌 #으로 시작하는 줄은 전부 건너뛰어 "### 제목", "#1 ..." 같은 줄이
#        본문에서 경고 없이 빠지던 문제 - 건너뛰는 줄을 제목 줄("# ")과 해시태그 줄
#        (단어 절반 이상이 #)로 좁힘. "###"~"######" 제목은 기호를 떼고 일반 문단으로
#        입력함(소제목 인식은 기존대로 "## "만 - 인용구·소제목 이미지 대상 아님).

