# 프롬프트 로딩 함수
def load_prompt(filename):
    """외부 프롬프트 파일 로드"""
    try:
        # 전체 경로면 그대로, 파일명만이면 기본 폴더 사용
        if os.path.isabs(filename) or os.path.exists(filename):
            prompt_path = filename
        else:
            prompt_path = os.path.join("Naver_blog_main_prompts", filename)

        logger.info(f"📂 프롬프트 로드 시도: {filename}")
        
        with open(prompt_path, 'r', encoding='utf-8') as f:
            content = f.read()
            logger.info(f"✅ 프롬프트 로드 성공: {filename} ({len(content)}자)")
            return content
            
    except FileNotFoundError:
        logger.error(f"❌ 프롬프트 파일 못 찾음: {filename}")
        logger.error(f"❌ 찾으려던 경로: {os.path.abspath(prompt_path)}")
        raise
    except Exception as e:
        logger.error(f"❌ 프롬프트 로드 실패: {str(e)}")
        raise


# 유저 에이젼트의 크롬버전 변수로 관리
_ENV_CONFIG_CACHE = None
def _load_env_config():
    """공용 환경설정 파일 로드 (key=value 형식, 캐싱) - Naver_blog_env_config/env.txt"""
    global _ENV_CONFIG_CACHE
    if _ENV_CONFIG_CACHE is not None:
        return _ENV_CONFIG_CACHE

    env = {}
    try:
        env_dir = os.path.join(BASE_DIR, "Naver_blog_env_config")
        env_path = os.path.join(env_dir, "env.txt")
        with open(env_path, 'r', encoding='utf-8') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#') or '=' not in line:
                    continue
                key, _, value = line.partition('=')
                env[key.strip()] = value.strip()
        logger.info(f"✅ 환경설정 로드 완료: {len(env)}개 항목")
    except FileNotFoundError:
        logger.info("env.txt 없음 - 기본값으로 동작")
    except Exception as e:
        logger.warning(f"env.txt 로드 실패: {e}")

    _ENV_CONFIG_CACHE = env
    return env

# 엑셀 표 가로폭 변수로 관리
def get_env_value(key, default=""):
    """환경설정 값 조회 (없으면 default 반환)"""
    env = _load_env_config()
    return env.get(key, default)

#로깅 설정
def setup_logging():
    logger = logging.getLogger()
    logger.setLevel(logging.INFO)  # INFO 레벨로 변경
    
    # 콘솔 핸들러는 INFO 유지 (터미널 출력용)
    console_handler = logging.StreamHandler()
    console_formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
    console_handler.setFormatter(console_formatter)
    console_handler.setLevel(logging.INFO)
    
    # 파일 핸들러는 ERROR만 기록
    error_log_file = f"error_log_{datetime.now().strftime('%Y%m%d_%H%M%S')}.log"
    file_handler = logging.FileHandler(error_log_file, encoding='utf-8')
    file_formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
    file_handler.setFormatter(file_formatter)
    file_handler.setLevel(logging.ERROR)
    
    logger.addHandler(console_handler)
    logger.addHandler(file_handler)
    
    return logger


logger = setup_logging()

