        # row=13: 폰트 선택
        font_selection_frame = ttk.LabelFrame(self.tab2, text="블로그 포스팅에 사용할 폰트", padding="3", style='Big.TLabelframe')
        font_selection_frame.grid(row=14, column=0, columnspan=3, sticky=(tk.W, tk.E), pady=1, padx=5)
        ttk.Label(font_selection_frame, text="포스팅 폰트 파일:", style='Title.TLabel').grid(row=0, column=0, sticky=tk.W, pady=1, padx=(5, 10))
        font_folder = "./Naver_font"
        font_files = []
        default_font = "SB_agro_B-기본값.ttf"
        if os.path.exists(font_folder):
            font_files = [f for f in os.listdir(font_folder) if f.endswith('.ttf')]
            font_files.sort()
        if default_font not in font_files:
            from tkinter import messagebox
            messagebox.showerror("기본 폰트 없음", f"기본 폰트 '{default_font}'가 Naver_font 폴더에 없습니다.\n\n폰트를 추가해주세요.")
            self.selected_font = tk.StringVar(value="")
        else:
            self.selected_font = tk.StringVar(value=default_font)
        if font_files:
            font_combo_container = ttk.Frame(font_selection_frame)
            font_combo_container.grid(row=0, column=1, sticky='w', pady=1, padx=5)
            font_combo = ttk.Combobox(font_combo_container, textvariable=self.selected_font,
                                      values=font_files, width=30, font=('나눔고딕', 10), state='readonly')
            font_combo.pack(side=tk.LEFT, padx=5)
            self.font_preview_label = ttk.Label(font_combo_container, text="폰트 미리보기",
                                                font=('나눔고딕', 14), relief="solid", borderwidth=1, padding=5)
            self.font_preview_label.pack(side=tk.LEFT, padx=5)
            def update_font_preview(event=None):
                selected = self.selected_font.get()
                if selected:
                    try:
                        font_path = os.path.join(font_folder, selected)
                        from PIL import Image, ImageDraw, ImageFont, ImageTk
                        img = Image.new('RGB', (150, 30), color='white')
                        draw = ImageDraw.Draw(img)
                        try:
                            pil_font = ImageFont.truetype(font_path, 20)
                            draw.text((5, 5), "가나다ABC123", font=pil_font, fill='black')
                            photo = ImageTk.PhotoImage(img)
                            self.font_preview_label.configure(image=photo, text="")
                            self.font_preview_label.image = photo
                        except Exception as e:
                            self.font_preview_label.configure(text="미리보기 실패", image="")
                    except Exception as e:
                        self.font_preview_label.configure(text="폰트 미리보기", image="")
            font_combo.bind('<<ComboboxSelected>>', update_font_preview)
            update_font_preview()
        else:
            ttk.Label(font_selection_frame, text="폰트 파일이 없습니다", foreground="red",
                      font=('나눔고딕', 11)).grid(row=0, column=1, sticky='w', padx=5)
